import{_ as e,o,c as a,ag as s}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Accounts","description":"","frontmatter":{"source":"setup/accounts.md"},"headers":[],"relativePath":"setup/accounts.md","filePath":"setup/accounts.md"}'),r={name:"setup/accounts.md"};function n(i,t,d,c,h,l){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h1><blockquote><p>Which accounts the course uses, when you need each one, and the settings to change on day one.</p></blockquote><p>Every account here is free and none needs a payment method. You are an adult with a GitHub account already, so this page is short: it says <em>when</em> each account is needed and <em>what to switch off</em>. Which product fills each slot, and its current limits, is in <a href="./../TOOLS.html#the-stack-at-a-glance">Tool Handout: The stack at a glance</a>.</p><h2 id="which-accounts-and-when" tabindex="-1">Which accounts, and when <a class="header-anchor" href="#which-accounts-and-when" aria-label="Permalink to &quot;Which accounts, and when&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Account</th><th>Needed?</th><th>Create it by</th><th>Used for</th></tr></thead><tbody><tr><td><strong>Canvas</strong> (your UIdaho sign-in)</td><td>Required</td><td>Before the first Seminar</td><td>Everything graded that is personal: the signed safety contract, reading responses, reflections, peer evaluations, graduate critiques. Never in a public repository</td></tr><tr><td><strong>GitHub</strong> (personal)</td><td>Required</td><td>Week 0</td><td>Every lab, the team project, CI, Codespaces</td></tr><tr><td><strong>GitHub Education</strong> (Student Developer Pack)</td><td>Required for the course&#39;s stack</td><td>Apply in week 0</td><td>Copilot Student; GitHub Pro&#39;s larger Codespaces and Actions allowances (<a href="./../TOOLS.html#the-github-student-developer-pack">what it gives</a>)</td></tr><tr><td><strong>Primary LLM API key</strong> (a personal Google account for AI Studio)</td><td>Required</td><td>Week 0</td><td>The kits (weeks 1, 3, 4, 11, 12) and Gemini CLI (weeks 2, 5, 8, 13)</td></tr><tr><td><strong>Fallback LLM API key</strong> (the fallback provider in TOOLS.md)</td><td>Required</td><td>Week 1</td><td>When the primary is rate-limited or down</td></tr><tr><td><strong>Chat assistant</strong> (Claude Free or ChatGPT Free; or Microsoft Copilot with your UIdaho sign-in)</td><td>Required</td><td>Week 0</td><td>Explaining, reviewing your reasoning, reading papers. Not a substitute for an agent in the labs</td></tr><tr><td><strong>Jules</strong> (your Google account)</td><td>Required for week 13</td><td>Week 12</td><td>The background agent in the parallel-agents lab and the team project</td></tr><tr><td><strong>CodeRabbit</strong> (sign in with GitHub)</td><td>Required for week 9</td><td>Week 9</td><td>The AI reviewer on your public team fork</td></tr><tr><td><strong>Zed Student</strong></td><td>Optional</td><td>Any time</td><td>IDE agent fallback (18+, GitHub account older than 30 days, university email)</td></tr><tr><td><strong>OpenRouter</strong></td><td>Optional</td><td>Any time</td><td>A spare free pool</td></tr><tr><td><strong>OpenAI Codex student credits</strong></td><td>Optional, untested by the course</td><td>Wait for the instructor&#39;s week 0 test</td><td>A possible extra pool (<a href="./../TOOLS.html#other-student-offers">Tool Handout: Other student offers</a>)</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>When a service offers <strong>Sign in with GitHub</strong> and then asks for repository access, choose <strong>Only select repositories</strong> and pick the one repository it needs. An app with access to every repository you own is a large blast radius for a review bot.</p></div><h2 id="github-and-the-student-developer-pack" tabindex="-1">GitHub and the Student Developer Pack <a class="header-anchor" href="#github-and-the-student-developer-pack" aria-label="Permalink to &quot;GitHub and the Student Developer Pack&quot;">​</a></h2><p>Apply at <a href="https://github.com/education/students" target="_blank" rel="noreferrer">education.github.com</a> with your UIdaho email or a photo of your student ID. Verification takes days, and GitHub re-checks eligibility monthly. GitHub has paused new Copilot Student sign-ups before (<a href="./../TOOLS.html#the-github-student-developer-pack">Tool Handout: The GitHub Student Developer Pack</a>), so apply early and use Copilot Free while you wait.</p><p>What matters for the course:</p><ul><li><strong>Copilot Student&#39;s model allowance is tiny.</strong> Use it for completions and Ask mode, and for occasional short agent runs. The course&#39;s heavy agent work runs on other free pools and the lab machine (<a href="./../TOOLS.html#spreading-the-work-across-free-allowances">spreading the work</a>). Don&#39;t set a paid budget to keep going: switch tools instead.</li><li><strong>Codespaces hours are core-weighted.</strong> A 4-core machine uses your hours twice as fast as a 2-core one. Use the smallest machine that builds the class codebase, and stop it when you finish.</li><li><strong>Actions is free on public repositories.</strong> Team forks are public, so CI costs nothing there. Private repositories draw on a monthly entitlement.</li></ul><h2 id="privacy-settings" tabindex="-1">Privacy settings <a class="header-anchor" href="#privacy-settings" aria-label="Permalink to &quot;Privacy settings&quot;">​</a></h2><p>Change these before you type anything. The data rule still applies whatever the settings say: public open-source code and course kits only (<a href="./safety-contract.html#1-the-data-rule">contract rule 1</a>).</p><table tabindex="0"><thead><tr><th>Tool</th><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td><strong>GitHub Copilot</strong></td><td><a href="https://github.com/settings/copilot/features" target="_blank" rel="noreferrer">github.com/settings/copilot/features</a> → disable use of your data for training; <strong>Suggestions matching public code</strong> → Block</td><td>One setting covers Copilot in Codespaces, VS Code and Copilot CLI. No student exemption is stated</td></tr><tr><td><strong>Claude</strong></td><td>Settings → Privacy → <strong>Help improve Claude</strong> off</td><td>Use incognito chats for anything you&#39;d rather not keep</td></tr><tr><td><strong>ChatGPT</strong></td><td>Settings → Data controls → <strong>Improve the model for everyone</strong> off</td><td>Temporary chats aren&#39;t used for training</td></tr><tr><td><strong>Microsoft Copilot (UIdaho)</strong></td><td>Sign in with your UIdaho account</td><td>What protection students get is unverified; follow the data rule</td></tr><tr><td><strong>Google AI Studio and the Gemini API</strong></td><td><strong>No opt-out on the free tier</strong>; human reviewers may read prompts</td><td>Public code and course kits only</td></tr><tr><td><strong>VS Code</strong></td><td>Settings → <code>telemetry</code> → <strong>Telemetry Level</strong> off</td><td>Optional</td></tr><tr><td><strong>GitHub</strong></td><td>Settings → Emails → <strong>Keep my email addresses private</strong> and <strong>Block command line pushes that expose my email</strong></td><td>Your commits are public in team forks</td></tr></tbody></table><p>Menus move. If a setting has moved, ask the tool&#39;s assistant where it is, and tell your instructor so this page can be fixed.</p><h2 id="one-free-llm-api-key" tabindex="-1">One free LLM API key <a class="header-anchor" href="#one-free-llm-api-key" aria-label="Permalink to &quot;One free LLM API key&quot;">​</a></h2><p>The kits read <code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code> and <code>LLM_MODEL</code> and work with any OpenAI-compatible provider, so the key you choose is a configuration detail, not a commitment. Get the primary key from <a href="./../TOOLS.html#llm-apis-for-the-kits">Tool Handout: LLM APIs for the kits</a> in week 0 and a fallback key in week 1. Both accounts must have <strong>no payment method</strong>: on a free tier, that is the hard spending cap (<a href="./safety-contract.html#6-spending-caps-at-zero">contract rule 6</a>). How to store and use them: <a href="./api-keys.html">API Keys, Tokens and Spending Caps</a>.</p><p>Use a <strong>personal</strong> Google account for AI Studio. Institutional accounts may have it switched off, and their terms differ.</p><h2 id="the-chat-assistant" tabindex="-1">The chat assistant <a class="header-anchor" href="#the-chat-assistant" aria-label="Permalink to &quot;The chat assistant&quot;">​</a></h2><p>The chat assistant is for thinking, not for the labs&#39; agent work: explaining a paper&#39;s method, checking your reasoning about a design, drafting questions for a maintainer (which you then rewrite in your own words). Graded writing (reading responses, reflections, PR descriptions, review comments you sign, critiques) is 🔴 AI off (<a href="./../SYLLABUS.html">syllabus</a>).</p><p>Use one primary assistant and know your fallback. When you quote what an assistant told you in a report, tag it <strong>inferred</strong> until you&#39;ve checked it yourself.</p><h2 id="canvas" tabindex="-1">Canvas <a class="header-anchor" href="#canvas" aria-label="Permalink to &quot;Canvas&quot;">​</a></h2><p>Canvas holds everything graded that is personal. The rule is simple: if it&#39;s about you or names a classmate, it goes on Canvas; if it&#39;s code, specs, tests, <code>AI_LOG.md</code> or a PR, it goes in the repository.</p><table tabindex="0"><thead><tr><th>On Canvas</th><th>In the repository</th></tr></thead><tbody><tr><td>Signed safety contract (week 1)</td><td>Code, tests, specs, <code>DESIGN.md</code>, <code>TASKS.md</code></td></tr><tr><td>Reading responses (weekly, 🔴 AI off)</td><td><code>AI_LOG.md</code> and <code>Assisted-by:</code> trailers</td></tr><tr><td>Reflections and the team process retrospective&#39;s personal part</td><td><code>THREAT_MODEL.md</code>, <code>EVAL_PLAN.md</code></td></tr><tr><td>Peer evaluations of teammates</td><td>PR descriptions and review comments (public, professional, signed by you)</td></tr><tr><td>Graduate critiques, the study paper</td><td><code>STUDY_PROTOCOL.md</code> for graduate studies (no personal data in it)</td></tr></tbody></table><h2 id="security-hygiene" tabindex="-1">Security hygiene <a class="header-anchor" href="#security-hygiene" aria-label="Permalink to &quot;Security hygiene&quot;">​</a></h2><p>You know the basics. The course-specific points:</p><ul><li><strong>Two-factor authentication</strong> on GitHub and Google, with recovery codes in a password manager.</li><li><strong>A password manager holds your keys</strong>, not a notes app or a dotfile in a repository.</li><li><strong>Review authorized apps</strong> at github.com → Settings → Applications at the start of each team phase, and revoke what you no longer use.</li><li><strong>Revoke course keys and tokens at the end of the term.</strong> Any key that was ever pasted into a chat or committed is revoked the same day (<a href="./api-keys.html#if-a-key-leaks">API Keys, Tokens and Spending Caps: If a key leaks</a>).</li><li><strong>Keep course work separate from employer work.</strong> Don&#39;t open an employer&#39;s repository in a course Codespace, and don&#39;t connect course agents to work accounts.</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul><li>☐ Canvas sign-in works</li><li>☐ Personal GitHub account with 2FA, private email, recovery codes saved</li><li>☐ GitHub Education applied for</li><li>☐ Copilot and chat-assistant training settings off</li><li>☐ Primary LLM API key (week 0) and fallback key (week 1), no payment method on either</li><li>☐ Jules (by week 12) and CodeRabbit (week 9) when those weeks arrive</li></ul><p>Back to <a href="./">Week 0</a>.</p>',29)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
